steps.command:
set -eu
install -d -o root -g root -m 0755 /srv/infraset-cascade/catalog
printf '%s\n' '{"service":"catalog-api","status":"ok","node":"node2"}' > /srv/infraset-cascade/catalog/health.json
printf '%s\n' '{"catalog_version":7,"records":["alpha","bravo","charlie"]}' > /srv/infraset-cascade/catalog/records.json
chown root:root /srv/infraset-cascade/catalog/health.json /srv/infraset-cascade/catalog/records.json
chmod 0644 /srv/infraset-cascade/catalog/health.json /srv/infraset-cascade/catalog/records.json
cat > /etc/nginx/sites-available/infraset-cascade.conf <<'NGINX'
server {
    listen 18081;
    server_name _;
    access_log /var/log/nginx/catalog-access.log;
    error_log /var/log/nginx/catalog-error.log warn;

    location = /health {
        default_type application/json;
        alias /srv/infraset-cascade/catalog/health.json;
    }
}
NGINX
ln -sfn /etc/nginx/sites-available/infraset-cascade.conf /etc/nginx/sites-enabled/infraset-cascade.conf
rm -f /etc/nginx/sites-enabled/default
nginx -t
systemctl enable nginx.service >/dev/null
systemctl restart nginx.service
systemctl disable --now ssh.socket ssh.service 2>/dev/null || true
node3_ip="$(getent ahostsv4 node3 | awk 'NR == 1 {print $1}')"
ufw --force reset >/dev/null
ufw default deny incoming >/dev/null
ufw default allow outgoing >/dev/null
ufw allow from "$node3_ip" to any port 18081 proto tcp >/dev/null
ufw --force enable >/dev/null
curl -fsS http://127.0.0.1:18081/health | grep -Fq '"status":"ok"'

set -eu
